-- 2026 地方選舉公報索引（election_bulletins 的 2026 列）。
--
-- 問題：election_bulletins 只有 2022、2024，所以 2026 的補政見任務（policy_missing、term_policy_missing）
--   都找不到公報、帶不出 bulletin_urls，代理要自己去公報站翻目錄（目錄直連 403，很容易誤判「沒上架」）。
-- 做法：scripts/build-election-bulletins.ts --election 2026 --wrap，單位清單取自我們自己的參選紀錄
--   （politician_elections 的 filed／elected／not_elected join regions；2026 沒有 cec_candidates），
--   對 eebulletin.cec.gov.tw 115 年的全站清單（?action=sitemap），規則在 supabase/functions/_shared/election-bulletin.ts。
-- 只收對得到的單位；對不到的（依選區分檔看不出村里在哪一份、聯合公報、尚未上架）不寫，寧可少給不要給錯。
-- 同一支腳本的資料段，可重跑：ON CONFLICT 以新的清單為準。
